package com.afkalerts;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(AfkAlertsConfig.GROUP)
public interface AfkAlertsConfig extends Config
{
    String GROUP = "afkalerts";

    @ConfigItem(keyName="prayer", name="Prayer alert", description="Speak when prayer falls to or below your threshold.", position=0)
    default boolean prayer() { return true; }

    @Range(min=0, max=99)
    @ConfigItem(keyName="prayerThreshold", name="Prayer threshold", description="Prayer points, inclusive. Zero alerts only when prayer runs out. Restore above this value to rearm.", position=1)
    default int prayerThreshold() { return 10; }

    @Range(min=0, max=120)
    @ConfigItem(keyName="prayerRepeat", name="Prayer reminder (seconds)", description="Repeat while prayer stays low. Zero means one alert per threshold crossing.", position=2)
    default int prayerRepeat() { return 0; }

    @ConfigItem(keyName="aggression", name="Aggression timer alert", description="Uses the built-in NPC Aggression Timer. Enable and calibrate that plugin; configure its NPC names or Always active.", position=3)
    default boolean aggression() { return true; }

    @ConfigItem(keyName="divineCombat", name="Divine super combat expiry", description="Speak when the observed divine super combat timer ends.", position=4)
    default boolean divineCombat() { return true; }

    @ConfigItem(keyName="divineRanging", name="Divine ranging expiry", description="Speak when divine ranging ends.", position=5)
    default boolean divineRanging() { return false; }

    @ConfigItem(keyName="divineMagic", name="Divine magic expiry", description="Speak when divine magic ends.", position=6)
    default boolean divineMagic() { return false; }

    @ConfigItem(keyName="stamina", name="Stamina expiry", description="Speak when stamina potion duration ends.", position=7)
    default boolean stamina() { return false; }

    @ConfigItem(keyName="goading", name="Goading potion expiry", description="Separate from natural NPC aggression. Speak when the goading potion timer ends.", position=8)
    default boolean goading() { return false; }

    @ConfigItem(keyName="antifire", name="Antifire expiry", description="Speak when both regular and super antifire timers are inactive.", position=9)
    default boolean antifire() { return false; }

    @Range(min=0, max=100)
    @ConfigItem(keyName="volume", name="Voice volume", description="0 mutes speech; 100 is full volume. Independent of in-game sound settings.", position=10)
    default int volume() { return 80; }

    @ConfigItem(keyName="backgroundOnly", name="Only when unfocused", description="Speak only when RuneLite is unfocused or minimized. Off allows alerts while focused too.", position=11)
    default boolean backgroundOnly() { return false; }

    @ConfigItem(keyName="slayerComplete", name="Slayer task completed", description="Speak when the game announces your task completion. Skipping a task does not trigger it.", position=12)
    default boolean slayerComplete() { return true; }

    @ConfigItem(keyName="superior", name="Superior foe appeared", description="Speak when the game announces a superior Slayer monster. Does not require the Slayer plugin.", position=13)
    default boolean superior() { return true; }

    @ConfigItem(keyName="pace", name="Speaking pace", description="Pitch-preserving Relaxed, Natural or Brisk speech. Preview before saving.", position=-1)
    default SpeakingPace pace() { return SpeakingPace.RELAXED; }
}

package com.afkalerts;

import com.google.inject.Provides;
import java.time.Instant;
import java.util.EnumMap;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.npcunaggroarea.NpcAggroAreaPlugin;
import net.runelite.client.ui.ClientUI;

@PluginDescriptor(name="AFK Alerts",
    description="Offline voice alerts for prayer, aggression, potions and Slayer tasks",
    tags={"audio", "voice", "afk", "prayer", "aggro", "divine", "notifications"})
public class AfkAlertsPlugin extends Plugin
{
    @Inject private Client client;
    @Inject private AudioPlayer audioPlayer;
    @Inject private ScheduledExecutorService scheduler;
    @Inject private ClientThread clientThread;
    @Inject private AfkAlertsConfig config;
    @Inject private PluginManager pluginManager;
    @Inject private ClientUI clientUI;
    private AlertTracker tracker = new AlertTracker();
    private SlayerAlerts slayer = new SlayerAlerts();
    private final Map<VoiceLine, AlertTracker.Effect> effects = new EnumMap<>(VoiceLine.class);
    private volatile VoicePlayer voice;

    @Provides AfkAlertsConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(AfkAlertsConfig.class);
    }

    @Override protected void startUp() throws Exception
    {
        reset();
        voice = new VoicePlayer(audioPlayer, scheduler);
    }

    @Override protected void shutDown()
    {
        VoicePlayer old = voice;
        voice = null;
        if (old != null) { old.close(); }
        reset();
    }

    private void reset()
    {
        VoicePlayer player = voice;
        if (player != null) { player.clear(); }
        tracker = new AlertTracker();
        slayer = new SlayerAlerts();
        effects.clear();
    }

    @Subscribe public void onConfigChanged(ConfigChanged event)
    {
        if (AfkAlertsConfig.GROUP.equals(event.getGroup())
            && "pace".equals(event.getKey()))
        {
            VoicePlayer player = voice;
            if (player != null) { player.clear(); }
            return;
        }
        if (AfkAlertsConfig.GROUP.equals(event.getGroup())
            && !"volume".equals(event.getKey()) && !"backgroundOnly".equals(event.getKey()))
        {
            clientThread.invoke(this::reset);
        }
    }

    @Subscribe public void onGameStateChanged(GameStateChanged event)
    {
        GameState state = event.getGameState();
        if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING
            || state == GameState.CONNECTION_LOST || state == GameState.LOGGING_IN)
        {
            reset();
        }
    }

    @Subscribe public void onActorDeath(ActorDeath event)
    {
        if (event.getActor() == client.getLocalPlayer()) { reset(); }
    }

    @Subscribe(priority=-10) public void onGameTick(GameTick event)
    {
        if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null) { return; }
        if (client.getBoostedSkillLevel(Skill.HITPOINTS) <= 0) { reset(); return; }
        long now = System.currentTimeMillis();
        boolean audible = voice != null && config.volume() > 0 && (!config.backgroundOnly() || !clientUI.isFocused());
        if (slayer.take(VoiceLine.SLAYER_COMPLETE, now, config.slayerComplete(), audible)) { speak(VoiceLine.SLAYER_COMPLETE); }
        if (slayer.take(VoiceLine.SUPERIOR, now, config.superior(), audible)) { speak(VoiceLine.SUPERIOR); }
        int points = client.getBoostedSkillLevel(Skill.PRAYER);
        if (config.prayer() && tracker.prayer(points, config.prayerThreshold(), config.prayerRepeat(), now, audible))
        {
            speak(points == 0 ? VoiceLine.EMPTY_PRAYER : VoiceLine.PRAYER);
        }

        NpcAggroAreaPlugin aggression = null;
        for (Plugin plugin : pluginManager.getPlugins())
        {
            if (plugin instanceof NpcAggroAreaPlugin && pluginManager.isPluginActive(plugin))
            {
                aggression = (NpcAggroAreaPlugin) plugin;
                break;
            }
        }
        Instant end = aggression != null && aggression.isActive() ? aggression.getEndTime() : null;
        Long deadline = config.aggression() && end != null ? end.toEpochMilli() : null;
        if (tracker.aggression(deadline, now, audible)) { speak(VoiceLine.AGGRESSION); }

        effect(VoiceLine.DIVINE_COMBAT, config.divineCombat(), audible, VarbitID.DIVINECOMBAT_POTION_TIME);
        effect(VoiceLine.DIVINE_RANGING, config.divineRanging(), audible, VarbitID.DIVINERANGE_POTION_TIME);
        effect(VoiceLine.DIVINE_MAGIC, config.divineMagic(), audible, VarbitID.DIVINEMAGIC_POTION_TIME);
        effect(VoiceLine.STAMINA, config.stamina(), audible, VarbitID.STAMINA_DURATION);
        effect(VoiceLine.GOADING, config.goading(), audible, VarbitID.GOADING_POTION_TIMER);
        effect(VoiceLine.ANTIFIRE, config.antifire(), audible, VarbitID.ANTIFIRE_POTION, VarbitID.SUPER_ANTIFIRE_POTION);

    }

    @Subscribe public void onChatMessage(ChatMessage event)
    {
        if (client.getGameState() != GameState.LOGGED_IN) { return; }
        VoiceLine line = SlayerAlerts.classify(event.getType(), event.getMessage());
        if (line == VoiceLine.SLAYER_COMPLETE && config.slayerComplete()
            || line == VoiceLine.SUPERIOR && config.superior())
        {
            slayer.record(line, System.currentTimeMillis());
        }
    }

    private void effect(VoiceLine line, boolean enabled, boolean audible, int... varbits)
    {
        if (!enabled) { effects.remove(line); return; }
        boolean active = false;
        for (int varbit : varbits) { active |= client.getVarbitValue(varbit) > 0; }
        if (effects.computeIfAbsent(line, key -> new AlertTracker.Effect()).update(active, audible)) { speak(line); }
    }

    private void speak(VoiceLine line)
    {
        VoicePlayer player = voice;
        if (player != null) { player.speak(line, config.volume(), config.pace()); }
    }

}

package com.afkalerts;

/** State only: no client access, audio, or wall-clock dependency. */
final class AlertTracker
{
    private Integer previousPrayer;
    private long lastPrayerAlert;
    private boolean prayerPending;
    private Long aggressionDeadline;
    private boolean aggressionArmed;

    boolean prayer(int points, int threshold, int repeatSeconds, long now, boolean canSpeak)
    {
        if (points > threshold)
        {
            prayerPending = false;
            lastPrayerAlert = 0;
        }
        else if (previousPrayer != null && previousPrayer > threshold)
        {
            prayerPending = true;
        }
        boolean due = prayerPending || (lastPrayerAlert != 0 && repeatSeconds > 0
            && now - lastPrayerAlert >= repeatSeconds * 1000L);
        previousPrayer = points;
        if (points <= threshold && due && canSpeak)
        {
            prayerPending = false;
            lastPrayerAlert = now;
            return true;
        }
        return false;
    }

    boolean aggression(Long deadline, long now, boolean canSpeak)
    {
        if (deadline == null)
        {
            aggressionDeadline = null;
            aggressionArmed = false;
            return false;
        }
        if (!deadline.equals(aggressionDeadline))
        {
            aggressionDeadline = deadline;
            // An already expired timer on startup is not a newly observed expiry.
            aggressionArmed = deadline > now;
        }
        if (aggressionArmed && now >= deadline && canSpeak)
        {
            aggressionArmed = false;
            return true;
        }
        return false;
    }

    static final class Effect
    {
        private boolean active;
        private boolean pending;

        boolean update(boolean current, boolean canSpeak)
        {
            if (current)
            {
                pending = false;
            }
            else if (active)
            {
                pending = true;
            }
            active = current;
            if (pending && canSpeak)
            {
                pending = false;
                return true;
            }
            return false;
        }
    }
}

package com.afkalerts;

import java.util.EnumMap;
import java.util.Map;
import java.util.regex.Pattern;
import net.runelite.api.ChatMessageType;

/** Accept server messages only, never player chat or task-counter resets. */
final class SlayerAlerts
{
    private static final Pattern COMPLETED = Pattern.compile(
        "^(?:You've|You have) completed (?:your (?:Slayer )?task[!.].*|(?:at least )?[\\d,]+ (?:Wilderness )?tasks?\\b.*(?:received|Slayer master|Slayer Master).*)$");
    private final Map<VoiceLine, Long> pending = new EnumMap<>(VoiceLine.class);
    private final Map<VoiceLine, Long> last = new EnumMap<>(VoiceLine.class);

    static VoiceLine classify(ChatMessageType type, String message)
    {
        if (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM) { return null; }
        String text = message.replaceAll("<[^>]*>", "").replace('\u00a0', ' ').trim();
        if (text.equals("A superior foe has appeared...")) { return VoiceLine.SUPERIOR; }
        return COMPLETED.matcher(text).matches() ? VoiceLine.SLAYER_COMPLETE : null;
    }

    void record(VoiceLine line, long now)
    {
        Long previous = last.get(line);
        if (previous == null || now - previous >= 2000)
        {
            last.put(line, now);
            pending.put(line, now);
        }
    }

    boolean take(VoiceLine line, long now, boolean enabled, boolean audible)
    {
        Long recorded = pending.get(line);
        if (recorded == null) { return false; }
        if (!enabled || now - recorded > 30000) { pending.remove(line); return false; }
        if (!audible) { return false; }
        pending.remove(line);
        return true;
    }
}

package com.afkalerts;

public enum SpeakingPace
{
    RELAXED("relaxed", "Relaxed"),
    NATURAL("natural", "Natural"),
    BRISK("brisk", "Brisk");
    final String folder;
    private final String label;
    SpeakingPace(String folder, String label) { this.folder = folder; this.label = label; }
    @Override public String toString() { return label; }
}

package com.afkalerts;

enum VoiceLine
{
    PRAYER("prayer", "Your prayer is low."),
    EMPTY_PRAYER("empty-prayer", "You have run out of prayer."),
    AGGRESSION("aggression", "Your monster aggression timer has expired."),
    DIVINE_COMBAT("divine-combat", "Your divine super combat has expired."),
    DIVINE_RANGING("divine-ranging", "Your divine ranging potion has expired."),
    DIVINE_MAGIC("divine-magic", "Your divine magic potion has expired."),
    STAMINA("stamina", "Your stamina potion has expired."),
    GOADING("goading", "Your goading potion has expired."),
    ANTIFIRE("antifire", "Your antifire protection has expired."),
    SLAYER_COMPLETE("slayer-complete", "Your Slayer task is complete."),
    SUPERIOR("superior", "A superior foe has appeared.");

    String resource(SpeakingPace pace) { return "voices/3/" + pace.folder + "/" + file + ".wav"; }

    final String file;
    final String text;
    VoiceLine(String file, String text) { this.file = file; this.text = text; }
}

package com.afkalerts;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import net.runelite.client.audio.AudioPlayer;
import org.slf4j.LoggerFactory;

/** Serial playback through RuneLite's audio manager, off the game thread. */
final class VoicePlayer implements AutoCloseable
{
    private final AudioPlayer audioPlayer;
    private final ScheduledExecutorService scheduler;
    private final Deque<Announcement> queue = new ArrayDeque<>();
    private ScheduledFuture<?> pending;
    private boolean closed;

    VoicePlayer(AudioPlayer audioPlayer, ScheduledExecutorService scheduler)
    {
        this.audioPlayer = audioPlayer;
        this.scheduler = scheduler;
    }

    synchronized void speak(VoiceLine line, int volume, SpeakingPace pace)
    {
        if (closed || volume <= 0 || queue.size() >= 12) { return; }
        queue.addLast(new Announcement(line, volume, pace));
        if (pending == null)
        {
            pending = scheduler.schedule(this::playNext, 0, TimeUnit.MILLISECONDS);
        }
    }

    private synchronized void playNext()
    {
        pending = null;
        if (closed) { return; }
        Announcement next;
        while ((next = queue.pollFirst()) != null)
        {
            if (System.nanoTime() - next.queued > TimeUnit.SECONDS.toNanos(30)) { continue; }
            try (InputStream input = VoicePlayer.class.getResourceAsStream(next.line.resource(next.pace)))
            {
                if (input == null) { throw new IOException("Missing voice recording"); }
                byte[] data = input.readAllBytes();
                long duration = durationMillis(data);
                float gain = (float) (20.0 * Math.log10(Math.min(100, next.volume) / 100.0));
                audioPlayer.play(new ByteArrayInputStream(data), gain);
                // RuneLite owns playback. Schedule the next phrase without blocking
                // a worker or interrupting an announcement already playing.
                pending = scheduler.schedule(this::playNext, duration + 100, TimeUnit.MILLISECONDS);
                return;
            }
            catch (Exception e)
            {
                LoggerFactory.getLogger(VoicePlayer.class).warn("Voice playback failed", e);
            }
        }
    }

    private static final class Announcement
    {
        final VoiceLine line;
        final int volume;
        final SpeakingPace pace;
        final long queued = System.nanoTime();
        Announcement(VoiceLine line, int volume, SpeakingPace pace)
        {
            this.line = line;
            this.volume = volume;
            this.pace = pace;
        }
    }

    static long durationMillis(byte[] wav) throws IOException
    {
        ByteBuffer buffer = ByteBuffer.wrap(wav).order(ByteOrder.LITTLE_ENDIAN);
        if (wav.length < 12 || buffer.getInt(0) != 0x46464952
            || buffer.getInt(8) != 0x45564157) { throw new IOException("Invalid WAV header"); }
        long byteRate = 0;
        long dataSize = -1;
        int offset = 12;
        while (offset <= wav.length - 8)
        {
            int kind = buffer.getInt(offset);
            long size = Integer.toUnsignedLong(buffer.getInt(offset + 4));
            long end = offset + 8L + size;
            if (end > wav.length) { throw new IOException("Truncated WAV chunk"); }
            if (kind == 0x20746d66 && size >= 16)
            {
                byteRate = Integer.toUnsignedLong(buffer.getInt(offset + 16));
            }
            if (kind == 0x61746164) { dataSize = size; }
            long next = end + (size & 1);
            if (next > wav.length) { break; }
            offset = (int) next;
        }
        if (byteRate == 0 || dataSize < 0) { throw new IOException("Missing WAV audio data"); }
        return (dataSize * 1000 + byteRate - 1) / byteRate;
    }

    synchronized void clear()
    {
        queue.clear();
    }

    @Override public synchronized void close()
    {
        closed = true;
        queue.clear();
        if (pending != null)
        {
            pending.cancel(false);
            pending = null;
        }
        // The injected scheduler belongs to RuneLite; leave its lifecycle alone.
    }
}

package com.afkalerts;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class AfkAlertsPluginTest
{
